class UnsafeAccount {
    private double balance;
    public void setBalance(double balance) {
        this.balance = balance;
    }
    public double getBalance() {
        return balance;
    }
}

class SafeAccount {
    private double balance;
    SafeAccount(double openingBalance) {
        if (openingBalance < 0) {
            throw new IllegalArgumentException("Opening balance cannot be negative");
        }
        this.balance = openingBalance;
    }
    public void deposit(double amount) {
        if (amount <= 0) {
            throw new IllegalArgumentException("Deposit must be positive");
        }
        balance += amount;
    }
    public double getBalance() {
        return balance;
    }
}

public class Main {
    public static void main(String[] args) {
        UnsafeAccount unsafe = new UnsafeAccount();
        unsafe.setBalance(-500);
        System.out.println("Unsafe balance: " + unsafe.getBalance());
        SafeAccount safe = new SafeAccount(1000);
        safe.deposit(200);
        System.out.println("Safe balance: " + safe.getBalance());
    }
}

class BankAccount {
    private long balanceInPaise;
    BankAccount(double openingRupees) {
        if (openingRupees < 0) {
            throw new IllegalArgumentException();
        }
        this.balanceInPaise = Math.round(openingRupees * 100);
    }
    void deposit(double rupees) {
        if (rupees <= 0) {
            throw new IllegalArgumentException();
        }
        balanceInPaise += Math.round(rupees * 100);
    }
    double getBalance() {
        return balanceInPaise / 100.0;
    }
}

public class Main {
    public static void main(String[] args) {
        BankAccount account = new BankAccount(100);
        account.deposit(50);
        System.out.println(account.getBalance());
    }
}

