interface PaymentGateway {
    void pay(int amount);
}

class WalletGateway implements PaymentGateway {
    private int walletBalance = 1000;
    @Override
    public void pay(int amount) {
        if (amount <= 0 || amount > walletBalance) {
            throw new IllegalArgumentException("Invalid payment");
        }
        walletBalance -= amount;
        System.out.println("Paid " + amount + ", remaining=" + walletBalance);
    }
}

public class Main {
    public static void main(String[] args) {
        PaymentGateway gateway = new WalletGateway();
        gateway.pay(400);
    }
}

interface ReceiptPrinter {
    void printBody(int amount);
    default void printReceipt(int amount) {
        System.out.println(formatHeader());
        printBody(amount);
    }
    private String formatHeader() {
        return "=== RECEIPT ===";
    }
    static boolean isValidAmount(int amount) {
        return amount > 0;
    }
}

class UpiReceiptPrinter implements ReceiptPrinter {
    @Override
    public void printBody(int amount) {
        System.out.println("UPI Paid: " + amount);
    }
}

public class Main {
    public static void main(String[] args) {
        if (ReceiptPrinter.isValidAmount(500)) {
            ReceiptPrinter printer = new UpiReceiptPrinter();
            printer.printReceipt(500);
        }
    }
}

