interface PaymentMethod {
    void pay(int amount);
}

class CardPayment implements PaymentMethod {
    private int limit = 1000;
    @Override
    public void pay(int amount) {
        if (amount <= limit) {
            limit -= amount;
            System.out.println("Card paid: " + amount);
        }
    }
}

class RewardCardPayment extends CardPayment {
    @Override
    public void pay(int amount) {
        super.pay(amount);
        System.out.println("Reward points: " + (amount / 10));
    }
}

public class Main {
    public static void main(String[] args) {
        PaymentMethod method = new RewardCardPayment();
        method.pay(500);
    }
}

