    @Override
    public int apply(int price) {
        return price - 250;
    }
}

class Cart {
    private DiscountPolicy policy;
    Cart(DiscountPolicy policy) {
        this.policy = policy;
    }
    void setPolicy(DiscountPolicy policy) {
        this.policy = policy;
    }
    int checkout(int price) {
        return policy.apply(price);
    }
}

public class Main {
